var i=[{title:`Rallenta gradualmente`,text:`Dopo una corsa o una pedalata dura, cammina o pedala con calma per qualche minuto invece di fermarti di colpo a pieno sforzo. Dopo il lavoro di forza, una breve camminata rilassata e un respiro normale possono farti sentire bene. Fermarsi bruscamente può talvolta dare capogiro, soprattutto dopo un’attività lunga e vigorosa.`},{title:`Mobilità leggera facoltativa`,text:`Puoi aggiungere movimenti comodi per polpacci, anche, petto o spalle se la flessibilità è uno dei tuoi obiettivi o semplicemente ti piacciono. Punta a una leggera sensazione di allungamento e non forzare grandi range. Uno stretching profondo subito dopo una sessione faticosa è facoltativo, e uno stretching doloroso lavora contro di te.`},{title:`Cosa mostrano le evidenze`,text:`Un movimento leggero può rendere più comodi i primi minuti dopo un allenamento. Ci sono poche evidenze che un defaticamento standard o una routine di stretching prevengano in modo affidabile il dolore muscolare del giorno dopo (DOMS). Progressione graduale, sonno e recupero contano comunque. Un defaticamento non cura un infortunio e non sostituisce le cure mediche.`},{title:`Adattalo alla sessione`,text:`Una camminata moderata può finire con uno o due minuti facili. Dopo una sessione di intervalli dura, dedica diversi minuti a movimento facile e respiro finché ti senti stabile. Se capogiro, mancanza di fiato insolita, dolore al petto o senso di svenimento non passano, interrompi l’allenamento e chiedi aiuto medico.`}];var a=[{label:`NHS: esercizi leggeri di defaticamento`,url:`https://www.nhs.uk/live-well/exercise/strength-and-resistance/body-blast-cool-down/`},{label:`ACE 2026: indicazioni pratiche sullo stretching`,url:`https://www.acefitness.org/continuing-education/certified/april-2026/9104/new-expert-guidance-on-stretching-what-belongs-in-your-programs/?authorScope=80`},{label:`NHS: dolore muscolare a insorgenza ritardata`,url:`https://www.leicspart.nhs.uk/msk-physiotherapy-resources-getting-started/msk-physiotherapy-resources-faqs/`}];var n={sections:i,sources:a};export{n as default,i as sections,a as sources};